(()=>{var n="foodit-pwa-cache";self.addEventListener("install",e=>{console.log("Service Worker instalado"),self.skipWaiting()});self.addEventListener("activate",e=>{console.log("Service Worker activado");let s=[n];e.waitUntil(caches.keys().then(i=>Promise.all(i.map(t=>{if(!s.includes(t))return caches.delete(t)}))))});self.addEventListener("fetch",e=>{console.log("Interceptando request:",e.request.url),e.respondWith(fetch(e.request))});})();
